<script setup lang="ts">
import WorkshopCharacterChoices from '../workshop/WorkshopCharacterChoices.vue'
import { scheduleAt, workshopSlots } from '../../../shared/homebrew-workshop'
import { applyWorkshopRules, boundClassLevel, ruleName } from '../../../shared/workshop-character'
import { computed, nextTick, onMounted, reactive, ref, watch } from 'vue'
import { useCharactersStore, type Character, type EquipmentItem } from '../../stores/characters'
import { useSheetLibrary } from '../../composables/useSheetLibrary'
import { ABILITY_KEYS, SKILL_ABILITY, abilityMod } from '../../lib/calc'
import { ORIGINS, pretty, resourcesFor, weaponProficient } from '../../lib/character-sheet'
import type { SrdSpell } from '../../lib/srd'
import SpellSlotEditor from './SpellSlotEditor.vue'
import ResourceEditor from './ResourceEditor.vue'
import { progressionClasses, slotsFor } from '../../../shared/character-progression'
import SpellPicker from '../pickers/SpellPicker.vue'
import SpellReferenceRepair from './SpellReferenceRepair.vue'
import { spellReferenceLabel } from '../../lib/spell-reference'
import { featResourceKey } from '../../../shared/feat-resources'
import { featNames } from '../../lib/feat-references'
import ItemComposer from '../items/ItemComposer.vue'
import { itemBonuses } from '../../../shared/item-rules'
import './character-editor.css'
const props=defineProps<{initialSection?:string;repairSpell?:string;repairOpen?:boolean}>()
const editorSection=ref(props.initialSection??'identity')
const sections=[['identity','Identity'],['rules','Rules & choices'],['stats','Stats & training'],['equipment','Equipment & attacks'],['spells','Spells & slots'],['resources','Resources'],['features','Features'],['bio','Notes']]
watch(()=>props.initialSection,value=>{if(value)editorSection.value=value})
onMounted(()=>{void library.loadEditorCatalogs()})
const emit = defineEmits<{ saved: []; dirty: [value:boolean] }>()
const store = useCharactersStore(), library = useSheetLibrary()
const draft = reactive<Character>(JSON.parse(JSON.stringify(store.current!)))
const baseline = ref(''), initial = ref<Character>(JSON.parse(JSON.stringify(draft)))
const error = ref(''), picker = ref(false), itemBusy = ref(false), featureSelection = ref('')
const itemCreateOpen=ref(false),itemAddedNotice=ref('')
let resetting=false
function reset() {
  resetting=true
  draft.companionKind=store.current!.companionKind
  Object.assign(draft, JSON.parse(JSON.stringify(store.current!)))
  draft.features = JSON.parse(JSON.stringify(library.features.value))
  draft.equipment = draft.equipment.map(i => ({ ...(library.items.value[i._id ?? i.name] ?? {}), ...i }))
  draft.resources = resourcesFor(draft)
  draft.spellcasting.slots = slotsFor(draft)
  draft.combat.acMode ??= 'manual'
  initial.value = JSON.parse(JSON.stringify(draft)); baseline.value = JSON.stringify(draft); error.value = ''
  void nextTick(()=>{resetting=false})
}
reset()
const dirty = computed(()=>JSON.stringify(draft)!==baseline.value)
watch(dirty,value=>emit('dirty',value),{immediate:true})
watch(library.loading,value=>{if(!value&&!dirty.value)reset()})
watch(()=>[draft.meta.klass,draft.meta.level] as const,()=>{if(!resetting&&draft.meta.classLevels?.length===1)draft.meta.classLevels[0]={name:draft.meta.klass,level:draft.meta.level}})
watch(()=>`${draft.meta.klass}:${draft.meta.subclass}:${draft.meta.race}:${draft.meta.level}:${JSON.stringify(draft.abilities)}:${JSON.stringify(draft.meta.classLevels)}`,()=>{if(resetting)return;Object.assign(draft,applyWorkshopRules(draft));draft.resources=resourcesFor(draft);draft.spellcasting.slots=slotsFor(draft)})
function linkRule(index:string,kind:'class'|'subclass'|'race'){const entry=library.ruleCatalog.value.find(r=>r.index===index);if(!entry)return;if(kind==='class'){draft.meta.classIndex=index;const match=draft.meta.classLevels?.find(e=>ruleName(e.name)===ruleName(entry.name));if(match)match.index=index}else if(kind==='race'){draft.meta.raceIndex=index;draft.meta.race=entry.name}else draft.meta.subclassIndex=index}
const addedSpells=ref<Record<string,SrdSpell>>({}),spellBusy=ref(false),spellRepairStatus=ref('')
const spellSwaps=new Map<string,string>()
const authoredCasting=computed(()=>[...(draft.homebrew?.bindings??[])].reverse().find(b=>b.rule.magic.enabled))
const spellAllowances=computed(()=>{
  const b=authoredCasting.value;if(!b)return null
  const l=boundClassLevel(draft,b.className),magic=b.rule.magic,active=l>=magic.startsAt
  return {cantrips:active?scheduleAt(magic.cantrips,l):0,spells:active?magic.learning==='prepared'?null:scheduleAt(magic.spells,l):0,prepared:active&&magic.learning!=='known'?Math.max(1,(magic.preparedLevel==='full'?l:magic.preparedLevel==='half'?Math.floor(l/2):0)+abilityMod(draft.abilities[magic.ability])+magic.preparedBase):null,maxLevel:Math.max(0,...Object.entries(workshopSlots(b.rule,l)).filter(([,n])=>n>0).map(([key])=>Number(key.slice(1))))}
})
const spellDetails=computed(()=>({...library.spells.value,...addedSpells.value}))
const spellCounts=computed(()=>({cantrips:draft.spellcasting.known.filter(id=>spellDetails.value[id]?.level===0).length,spells:draft.spellcasting.known.filter(id=>(spellDetails.value[id]?.level??0)>0).length,prepared:draft.spellcasting.prepared.filter(id=>(spellDetails.value[id]?.level??0)>0).length,missing:draft.spellcasting.known.filter(id=>!spellDetails.value[id]||spellDetails.value[id]?.definitionAvailable===false).length}))
const spellAllowanceProblems=computed(()=>{
  const limits=spellAllowances.value;if(!limits||draft.spellcasting.limitOverride||spellCounts.value.missing)return []
  const result:string[]=[]
  for(const key of ['cantrips','spells','prepared'] as const)if(limits[key]!==null&&spellCounts.value[key]>limits[key]!)result.push(`${key==='spells'?'Known / spellbook spells':key==='prepared'?'Prepared spells':'Cantrips'}: ${spellCounts.value[key]} selected, maximum ${limits[key]}. Remove a selection or enable the spell-choice override.`)
  if(draft.spellcasting.known.some(id=>(spellDetails.value[id]?.level??0)>limits.maxLevel))result.push(`This class has slots up to spell level ${limits.maxLevel}. Higher-level spells need the override.`)
  return result
})
const whole = (n:unknown,min:number,max:number)=>typeof n==='number'&&Number.isInteger(n)&&n>=min&&n<=max
const problems = computed(()=>{
  const result:string[]=[...spellAllowanceProblems.value]
  if(!draft.meta.name.trim()||!whole(draft.meta.level,1,20)||!whole(draft.meta.xp,0,Number.MAX_SAFE_INTEGER))result.push('Check the name, level, and experience.')
  if(ABILITY_KEYS.some(k=>!whole(draft.abilities[k],1,35)))result.push('Ability scores must be whole numbers from 1 to 35.')
  if(!whole(draft.combat.hpMax,1,9999)||!whole(draft.combat.ac,1,999)||!whole(draft.combat.speed,0,9999)||!whole(draft.combat.hitDiceTotal,0,99))result.push('Check maximum HP, armor class, speed, and hit dice.')
  if(draft.meta.classLevels?.length && (draft.meta.classLevels.some(c=>!c.name.trim()||!whole(c.level,1,20))||draft.meta.classLevels.reduce((sum,c)=>sum+c.level,0)!==draft.meta.level))result.push('Class levels must add up to your character level.')
  if(draft.equipment.some(i=>!i.name.trim()||!whole(i.qty,0,i.kind==='treasure'?Number.MAX_SAFE_INTEGER:9999)||!Number.isFinite(i.weight)||i.weight<0))result.push('Check inventory names, quantities, and weights.')
  if(draft.attacks.some(a=>!a.name.trim()||!whole(a.magicBonus,-99,99)||!whole(a.damageBonus,-999,999)))result.push('Check attack names and bonuses.')
  if(draft.resources?.some(r=>r.scaling&&(!whole(r.scaling.perLevel,0,999)||!whole(r.scaling.base,0,999))))result.push('Points per level and base points must be whole numbers from 0 to 999.')
  if(draft.resources?.some(r=>!r.name.trim()||!whole(r.max,0,999)||!whole(r.used,0,r.ruleId?999:r.max)))result.push('Resource totals must be between 0 and 999, with spent points no higher than the maximum.')
  if(draft.spellcasting.slotRule?.className&&!progressionClasses(draft).some(e=>e.name===draft.spellcasting.slotRule?.className))result.push('Choose an existing class for the spell slot progression, or use total character level.')
  if(draft.resources?.some(r=>r.scaling?.className&&!progressionClasses(draft).some(e=>e.name===r.scaling?.className)))result.push('Choose an existing class for each points-per-level tracker, or use total character level.')
  if(Object.values(draft.spellcasting.slots).some(s=>!whole(s.max,0,99)||!whole(s.used,0,draft.spellcasting.slotRule?.workshopId?999:s.max)))result.push('Check spell slots: maximum 0–99, spent no higher than the maximum.')
  if(draft.features.some(f=>!f.name.trim()||(f.level!==undefined&&!whole(f.level,1,20))))result.push('Features need a name and, when recorded, a gained level from 1 to 20.')
  return result
})
async function save() {
  if(store.saving||problems.value.length||itemBusy.value||spellBusy.value)return
  error.value=''
  const current=store.current!, before=initial.value
  // Sidebar XP awards and live resources are retained unless explicitly changed in this editor.
  const meta={...draft.meta,xp:draft.meta.xp===before.meta.xp?current.meta.xp:draft.meta.xp}
  const spellcasting=JSON.parse(JSON.stringify(draft.spellcasting)) as Character['spellcasting']
  for(const [key,slot] of Object.entries(spellcasting.slots))if(slot.used===before.spellcasting.slots[key]?.used&&current.spellcasting.slots[key])slot.used=current.spellcasting.slots[key]!.used
  const mapped=(id:string)=>{const seen=new Set<string>();while(spellSwaps.has(id)&&!seen.has(id)){seen.add(id);id=spellSwaps.get(id)!}return id}
  const originalPrepared=new Set(before.spellcasting.prepared.map(mapped)),livePrepared=new Set(current.spellcasting.prepared.map(mapped))
  spellcasting.prepared=[...new Set([...spellcasting.known,...spellcasting.prepared])].filter(id=>{const selected=spellcasting.prepared.includes(id);return selected===originalPrepared.has(id)?livePrepared.has(id):selected})
  const resources=draft.resources?.map(r=>{const original=before.resources?.find(v=>v.id===r.id),live=current.resources?.find(v=>v.id===r.id);return live&&original&&r.used===original.used?{...r,used:live.used}:r})
  const equipment=draft.equipment.map(item=>{const original=before.equipment.find(v=>v._id===item._id),live=current.equipment.find(v=>v._id===item._id);return item._id&&original&&live?{...item,qty:item.qty===original.qty?live.qty:item.qty,equipped:item.equipped===original.equipped?live.equipped:item.equipped}:item})
  const combat={...draft.combat}
  for(const key of ['hpCurrent','hpTemp','deathSavesSuccess','deathSavesFailure','inspiration','hitDiceUsed'] as const) if(draft.combat[key]===before.combat[key]) Object.assign(combat,{[key]:current.combat[key]})
  combat.hpCurrent=Math.max(0,combat.hpCurrent)
  try {
    await store.update(current._id,JSON.parse(JSON.stringify({companionKind:draft.companionKind??null,meta,combat,homebrew:draft.homebrew,abilities:draft.abilities,saves:draft.saves,skills:draft.skills,proficiencies:draft.proficiencies,attacks:draft.attacks,equipment,features:draft.features,spellcasting,resources})))
    baseline.value=JSON.stringify(draft);emit('dirty',false);emit('saved')
  } catch { error.value='Your edits are still here. Please try saving again.' }
}
function skill(key:string,expert:boolean){const current=draft.skills[key]??'none';draft.skills[key]=expert?(current==='expert'?'prof':'expert'):(current==='none'?'prof':'none')}
function addDraftItem(item:EquipmentItem){draft.equipment.push(item);itemAddedNotice.value=`${item.name} added to your draft. Save character to give it permanently.`}
function addAttack(item?:EquipmentItem){const w=item?.weapon;draft.attacks.push({name:item?.name??'New attack',ability:w?.ranged?'dex':w?.finesse&&draft.abilities.dex>draft.abilities.str?'dex':'str',range:w?.range??'Melee',damageDice:w?.dice??'1d8',damageType:w?.damageType??'slashing',damageBonus:0,magicBonus:item?.magicBonus??0,notes:'',addAbilityDamage:true})}
async function addSpell(index:string){
  if(draft.spellcasting.known.includes(index)){picker.value=false;return}
  try{addedSpells.value[index]=await library.resolveSpell(index)}catch{error.value='Spell details could not be loaded; counts may be incomplete.'}
  const detail=addedSpells.value[index],limits=spellAllowances.value
  if(detail&&limits&&!draft.spellcasting.limitOverride){const count=detail.level===0?spellCounts.value.cantrips:spellCounts.value.spells,maximum=detail.level===0?limits.cantrips:limits.spells
    if(maximum!==null&&count>=maximum||detail.level>limits.maxLevel){picker.value=false;error.value='This spell exceeds the saved class allowance. Enable the spell-choice override for extra grants or table rules.';return}}
  draft.spellcasting.known.push(index)
  if(!limits||limits.prepared===null||spellCounts.value.prepared<limits.prepared||detail?.level===0||draft.spellcasting.limitOverride)draft.spellcasting.prepared.push(index)
  picker.value=false
}
async function replaceSpell(before:string,after:string){if(before===after||spellBusy.value)return;spellBusy.value=true;spellRepairStatus.value='';try{addedSpells.value[after]=await library.resolveSpell(after);const swap=(ids:string[])=>[...new Set(ids.map(id=>id===before?after:id))];draft.spellcasting.known=swap(draft.spellcasting.known);draft.spellcasting.prepared=swap(draft.spellcasting.prepared);spellSwaps.set(before,after);error.value='';spellRepairStatus.value='Reference replaced with '+addedSpells.value[after]!.name+'. Save character to apply it.'}catch{error.value='That definition could not load. Your existing reference is unchanged.'}finally{spellBusy.value=false}}
function removeSpell(index:string){draft.spellcasting.known=draft.spellcasting.known.filter(i=>i!==index);draft.spellcasting.prepared=draft.spellcasting.prepared.filter(i=>i!==index)}
function addFeature(){const entry=library.featCatalog.value.find(f=>f.index===featureSelection.value);draft.features.push(entry?{name:entry.name,description:entry.description,origin:'feat',level:draft.meta.level}:{name:'New feature',description:'',origin:'other'});featureSelection.value=''}
function removeFeature(index:number){
  const feature=draft.features[index]!
  if(feature.origin==='feat')for(const legacy of draft.features.filter(f=>/^feats?$/i.test(f.name.trim())))legacy.description=featNames(legacy.description).filter(name=>featResourceKey(name)!==featResourceKey(feature.name)).join(', ')
  draft.features.splice(index,1)
}
function level(index:number,value:string){draft.features[index]!.level=value===''?undefined:Number(value)}
function proficiency(group:keyof Character['proficiencies'],value:string){draft.proficiencies[group]=[...new Set(value.split('\n').map(v=>v.trim()).filter(Boolean))]}
</script>
<template>
  <form class="sheet-editor" @submit.prevent="save"><header class="sheet-section-title" style="margin-bottom:22px"><p class="sheet-eyebrow">BUILD & REFINE</p><h2>Edit character</h2><p>Permanent changes stay in this draft until you save. Changing class or level does not silently replace your homebrew choices; review features, slots, resources, and HP here.</p></header><nav class="sheet-editor-navigation" aria-label="Edit character sections"><button v-for="[key,label] in sections" :key="key" type="button" class="sheet-button sheet-small-button" :aria-current="editorSection===key?'page':undefined" @click="editorSection=key">{{label}}</button></nav><p v-if="error" class="sheet-alert" role="alert">{{error}}</p><fieldset :disabled="store.saving||itemBusy||spellBusy">
    <section v-show="editorSection==='identity'" class="sheet-panel"><h3>Identity & advancement</h3><label class="sheet-checkbox" style="margin-bottom:12px"><input type="checkbox" :checked="draft.companionKind==='shadow-champion'" @change="draft.companionKind=($event.target as HTMLInputElement).checked?'shadow-champion':undefined" /> Available as a Shadow Champion</label><div class="sheet-form-grid"><label v-for="key in (['name','race','subrace','klass','subclass','background','alignment','portrait'] as const)" :key="key">{{key==='klass'?'Class':pretty(key)}}<input v-model="draft.meta[key]" :type="key==='portrait'?'url':'text'" :maxlength="key==='portrait'?2048:200" /></label><label>Character level<input v-model.number="draft.meta.level" type="number" min="1" max="20" /></label><label>Total experience<input v-model.number="draft.meta.xp" type="number" min="0" /></label></div><details class="sheet-details"><summary>Per-class levels · multiclass & resource calculations</summary><p class="sheet-small" style="margin:12px 0">For one class, leaving this empty uses the class and level above. Recorded class levels must add up to the character level.</p><div v-for="(entry,index) in draft.meta.classLevels" :key="index" class="sheet-inline" style="margin-bottom:10px"><label style="flex:1">Class name<input v-model="entry.name" /></label><label style="width:85px">Level<input v-model.number="entry.level" type="number" min="1" max="20" /></label><button type="button" class="sheet-button" @click="draft.meta.classLevels!.splice(index,1)">Remove</button></div><button type="button" class="sheet-button" @click="(draft.meta.classLevels??=[]).push({name:draft.meta.klass,level:draft.meta.level})">Add class level entry</button></details></section>
    <section v-show="editorSection==='rules'" class="sheet-panel" v-if="draft.homebrew?.bindings.length||library.ruleCatalog.value.length"><h3>Workshop rules & choices</h3><p class="sheet-small">Saved class and race rules supply their features, slots, and trackers. Choose a saved definition to resolve an ambiguous import.</p><div class="sheet-two-fields"><label>Saved class definition<select :value="draft.meta.classIndex??''" @change="linkRule(($event.target as HTMLSelectElement).value,'class')"><option value="">Keep current / automatic match</option><option v-for="entry in library.ruleCatalog.value.filter(r=>r.workshop?.kind==='class')" :key="entry.index" :value="entry.index">{{entry.displayName??entry.name}}</option></select></label><label>Saved subclass definition<select :value="draft.meta.subclassIndex??''" @change="linkRule(($event.target as HTMLSelectElement).value,'subclass')"><option value="">Keep current / automatic match</option><option v-for="entry in library.ruleCatalog.value.filter(r=>r.workshop?.kind==='subclass')" :key="entry.index" :value="entry.index">{{entry.displayName??entry.name}}</option></select></label><label>Saved race definition<select :value="draft.meta.raceIndex??''" @change="linkRule(($event.target as HTMLSelectElement).value,'race')"><option value="">Keep current / automatic match</option><option v-for="entry in library.ruleCatalog.value.filter(r=>r.workshop?.kind==='race')" :key="entry.index" :value="entry.index">{{entry.displayName??entry.name}}</option></select></label></div><template v-if="draft.homebrew"><div v-for="binding in draft.homebrew.bindings" :key="binding.ruleId" style="margin-top:18px"><p class="sheet-small">{{binding.rule.name}} · {{binding.revision?'saved revision '+binding.revision:'imported rules'}}</p><WorkshopCharacterChoices v-model="draft.homebrew.choices" :rules="[binding.rule]" :level="binding.rule.kind==='race'?draft.meta.level:boundClassLevel(draft,binding.className)" /></div></template></section>
    <section v-show="editorSection==='stats'" class="sheet-panel"><h3>Abilities & saving throws</h3><div class="sheet-form-grid"><label v-for="key in ABILITY_KEYS" :key="key" style="text-align:center">{{key.toUpperCase()}}<input v-model.number="draft.abilities[key]" type="number" min="1" max="35" style="text-align:center;font-size:24px" /><span class="sheet-checkbox" style="display:flex;justify-content:center;gap:7px;font-size:11px"><input v-model="draft.saves[key]" type="checkbox" :aria-label="`${key.toUpperCase()} saving throw proficiency`" /> Proficient save</span></label></div></section>
    <section v-show="editorSection==='stats'" class="sheet-panel"><h3>Skills</h3><p class="sheet-small">First circle: proficiency. Second circle: expertise. Expertise includes proficiency.</p><div v-for="(ability,key) in SKILL_ABILITY" :key="key" class="sheet-skill-row"><span class="sheet-skill-dots"><button type="button" :class="{filled:draft.skills[key]==='prof'||draft.skills[key]==='expert'}" :aria-label="`${pretty(key)} proficiency`" :aria-pressed="draft.skills[key]==='prof'||draft.skills[key]==='expert'" @click="skill(key,false)" /><button type="button" :class="{filled:draft.skills[key]==='expert'}" :aria-label="`${pretty(key)} expertise`" :aria-pressed="draft.skills[key]==='expert'" @click="skill(key,true)" /></span><span>{{pretty(key)}}<small>{{ability.toUpperCase()}}</small></span></div></section>
    <section v-show="editorSection==='stats'" class="sheet-panel"><h3>Defenses & movement</h3><div class="sheet-form-grid"><label>Armor class mode<select v-model="draft.combat.acMode"><option value="manual">Saved AC · custom rules / overrides</option><option value="equipment">Calculate from equipped armor</option></select></label><label>Base AC before accessory bonuses<input :value="draft.combat.ac-(draft.combat.itemAcBaseline??0)" type="number" min="1" :disabled="draft.combat.acMode==='equipment'" @input="draft.combat.ac=Number(($event.target as HTMLInputElement).value)+(draft.combat.itemAcBaseline??0)" /></label><label>Maximum HP<input v-model.number="draft.combat.hpMax" type="number" min="1" /></label><label>Speed · feet<input v-model.number="draft.combat.speed" type="number" min="0" /></label><label>Hit dice total<input v-model.number="draft.combat.hitDiceTotal" type="number" min="0" /></label></div><p class="sheet-small" style="margin-top:13px">Active accessory bonuses: {{itemBonuses(draft).ac}} AC and {{itemBonuses(draft).saves}} to all saving throws. Armor calculation uses known armor, shields, Dexterity, and item enchantments. Keep saved AC for special defenses such as Unarmored Defense or homebrew effects.</p></section>
    <section v-show="editorSection==='stats'" class="sheet-panel"><h3>Proficiencies & languages</h3><p class="sheet-small" style="margin-bottom:13px">One proficiency or language per line.</p><div class="sheet-two-fields"><label v-for="(values,group) in draft.proficiencies" :key="group">{{pretty(group)}}<textarea :value="values.join('\n')" rows="4" @change="proficiency(group,($event.target as HTMLTextAreaElement).value)" /></label></div></section>
    <section v-show="editorSection==='equipment'" class="sheet-panel"><div class="sheet-edit-heading"><h3>Inventory</h3><button type="button" class="sheet-button sheet-button-primary" @click="itemCreateOpen=true">+ Add or create item</button></div><p class="sheet-small">Choose an existing item or create a normal or magic item. Items added here are saved with your character draft.</p><p v-if="itemAddedNotice" class="sheet-notice" role="status">{{itemAddedNotice}}</p><details v-for="(item,index) in draft.equipment" :key="item._id??index" class="sheet-details"><summary>{{item.name}} · {{item.qty}} {{item.equipped?'· Equipped':''}}</summary><div class="sheet-form-grid" style="margin-top:15px"><label>Name<input v-model="item.name" /></label><label>Quantity<input v-model.number="item.qty" type="number" min="0" /></label><label>Weight · lb. each<input v-model.number="item.weight" type="number" min="0" step="0.01" /></label><label>Category<input v-model="item.category" /></label><label>Item enchantment<input v-model.number="item.magicBonus" type="number" /></label><label class="sheet-checkbox"><input v-model="item.requiresAttunement" type="checkbox" /> Requires attunement</label><label v-if="item.requiresAttunement" class="sheet-checkbox"><input v-model="item.attuned" type="checkbox" /> Attuned</label><label class="sheet-checkbox"><input v-model="item.equipped" type="checkbox" /> Equipped</label></div><label style="margin-top:13px">Notes<textarea v-model="item.notes" rows="2" /></label><label style="margin-top:13px">Description<textarea v-model="item.description" rows="3" /></label><div v-if="item.armor" class="sheet-form-grid" style="margin-top:12px"><label>Armor base / shield bonus<input v-model.number="item.armor.base" type="number" /></label><label>Dexterity cap<input v-model.number="item.armor.cap" type="number" /></label><label class="sheet-checkbox"><input v-model="item.armor.dex" type="checkbox" /> Add Dexterity</label></div><div class="sheet-filter-buttons" style="margin-top:13px"><button v-if="item.weapon" type="button" class="sheet-button" @click="addAttack(item)">Add weapon to attacks</button><button type="button" class="sheet-button" @click="draft.equipment.splice(index,1)">Remove item from draft</button></div></details></section>
    <section v-show="editorSection==='equipment'" class="sheet-panel"><div class="sheet-edit-heading"><h3>Attacks</h3><button type="button" class="sheet-button" @click="addAttack()">+ Attack</button></div><p class="sheet-small">Enchantment applies to both hit and damage. Extra damage is an additional modifier; the ability modifier is added separately.</p><details v-for="(a,index) in draft.attacks" :key="a._id??index" class="sheet-details" open><summary>{{a.name}}</summary><div class="sheet-form-grid" style="margin-top:15px"><label>Name<input v-model="a.name" /></label><label>Attack ability<select v-model="a.ability"><option v-for="key in ABILITY_KEYS" :key="key" :value="key">{{key.toUpperCase()}}</option></select></label><label>Damage dice<input v-model="a.damageDice" placeholder="1d8" /></label><label>Extra damage bonus<input v-model.number="a.damageBonus" type="number" /></label><label>Damage type<input v-model="a.damageType" /></label><label>Range<input v-model="a.range" /></label><label>Weapon enchantment<input v-model.number="a.magicBonus" type="number" /></label><label class="sheet-checkbox"><input type="checkbox" :checked="weaponProficient(draft,a)" @change="a.proficient=($event.target as HTMLInputElement).checked" /> Proficient with this attack</label><label class="sheet-checkbox"><input type="checkbox" :checked="a.addAbilityDamage!==false" @change="a.addAbilityDamage=($event.target as HTMLInputElement).checked" /> Add ability modifier to damage</label></div><label style="margin-top:13px">Notes<textarea v-model="a.notes" rows="2" /></label><button type="button" class="sheet-button" style="margin-top:12px" @click="draft.attacks.splice(index,1)">Remove attack from draft</button></details></section>
    <section v-show="editorSection==='spells'" class="sheet-panel"><h3>Spellbook & slot totals</h3><div v-if="spellAllowances" class="sheet-notice" style="margin:12px 0"><strong>{{authoredCasting?.rule.name}} · spell choices</strong><p>Cantrips {{spellCounts.cantrips}} / {{spellAllowances.cantrips}} · Known / book {{spellCounts.spells}} / {{spellAllowances.spells??'class list'}}<template v-if="spellAllowances.prepared!==null"> · Prepared {{spellCounts.prepared}} / {{spellAllowances.prepared}}</template></p><p v-if="spellCounts.missing">{{spellCounts.missing}} spell definitions are unavailable; counts cannot be fully checked.</p><label class="sheet-checkbox"><input v-model="draft.spellcasting.limitOverride" type="checkbox"/> Override spell-choice limits for grants or table rules</label></div><SpellReferenceRepair :ids="[...new Set([...draft.spellcasting.known,...draft.spellcasting.prepared])]" :details="spellDetails" :initial="repairSpell" :open="repairOpen" :busy="spellBusy" @replace="replaceSpell" /><p v-if="spellRepairStatus" class="sheet-notice" role="status">{{spellRepairStatus}}</p><details class="sheet-details" style="margin:12px 0"><summary>Spell slot totals & casting rules</summary><SpellSlotEditor :character="draft" @change="draft.spellcasting=$event" /></details><button type="button" class="sheet-button" @click="picker=true">+ Add spell</button><div v-for="index in [...new Set([...draft.spellcasting.known,...draft.spellcasting.prepared])]" :key="index" class="sheet-between sheet-edit-entry"><span>{{spellDetails[index]?.name??spellReferenceLabel(index)}}<small v-if="!spellDetails[index]||spellDetails[index]?.definitionAvailable===false" class="sheet-small" style="display:block">{{library.loading.value?'Loading definition…':'Definition unavailable · use Repair above'}}</small></span><label v-if="(spellDetails[index]?.level??0)>0" class="sheet-checkbox"><input type="checkbox" :checked="draft.spellcasting.prepared.includes(index)" @change="draft.spellcasting.prepared=($event.target as HTMLInputElement).checked?[...new Set([...draft.spellcasting.prepared,index])]:draft.spellcasting.prepared.filter(id=>id!==index)"/>Prepared</label><button type="button" class="sheet-button sheet-small-button" @click="removeSpell(index)">Remove from spellbook</button></div></section>
    <section v-show="editorSection==='resources'" class="sheet-panel"><ResourceEditor :character="draft" @change="draft.resources=$event" /></section>
    <section v-show="editorSection==='features'" class="sheet-panel"><div class="sheet-edit-heading"><h3>Features & traits</h3><button type="button" class="sheet-button" @click="featureSelection='';addFeature()">+ Custom feature</button></div><div class="sheet-inline"><label style="flex:1">Imported feats<select v-model="featureSelection"><option value="">Choose a feat…</option><option v-for="f in library.featCatalog.value" :key="f.index" :value="f.index">{{f.displayName??f.name}}</option></select></label><button type="button" class="sheet-button" :disabled="!featureSelection" @click="addFeature">Add feat</button></div><details v-for="(f,index) in draft.features" :key="f._id??index" class="sheet-details"><summary>{{f.name}} · {{ORIGINS[f.origin??'other']}}{{f.level?` · Level ${f.level}`:''}}</summary><div class="sheet-form-grid" style="margin-top:15px"><label>Name<input v-model="f.name" /></label><label>Origin<select v-model="f.origin"><option v-for="(label,key) in ORIGINS" :key="key" :value="key">{{label}}</option></select></label><label>Gained at level<input :value="f.level" type="number" min="1" max="20" placeholder="Unknown" @input="level(index,($event.target as HTMLInputElement).value)" /></label></div><label style="margin-top:12px">Description<textarea v-model="f.description" rows="5" /></label><div class="sheet-two-fields" style="margin-top:12px"><label class="sheet-checkbox"><input v-model="f.pinned" type="checkbox" /> Pin in Combat</label></div><button type="button" class="sheet-button" style="margin-top:12px" @click="removeFeature(index)">Remove feature from draft</button></details></section>
    <section v-show="editorSection==='bio'" class="sheet-panel"><h3>Biography & notes</h3><div class="sheet-two-fields"><label v-for="(_,key) in draft.personality" :key="key">{{pretty(key)}}<textarea v-model="draft.personality[key]" :rows="key==='backstory'?6:3" /></label></div></section>
  </fieldset><ItemComposer v-if="itemCreateOpen" mode="draft" @close="itemCreateOpen=false" @add="addDraftItem" /><ul v-if="problems.length" class="sheet-alert" role="alert"><li v-for="problem in problems" :key="problem">{{problem}}</li></ul><footer class="sheet-sticky-actions"><span>{{dirty?'Unsaved changes':'No unsaved changes'}}</span><button type="button" class="sheet-button" :disabled="store.saving||!dirty" @click="reset">Discard draft changes</button><button class="sheet-button sheet-button-primary" :disabled="store.saving||itemBusy||spellBusy||!!problems.length||!dirty">{{store.saving?'Saving…':'Save character'}}</button></footer><SpellPicker v-if="picker" @close="picker=false" @pick="addSpell" /></form>
</template>
